56	/* __tdata_size / __tbss_offset / __tbss_size are *absolute* linker symbols
57	 * (SIZEOF()/offset expressions), so their "address" is a small constant.
58	 * Under -mcmodel=medany the compiler materializes a symbol address with a
59	 * PC-relative auipc, and on RV64 the ~2GB gap between the code (0x80000000)
60	 * and a small absolute value overflows R_RISCV_PCREL_HI20. Read these
61	 * symbols with absolute lui/addi addressing instead. (RV32 happened to
62	 * work because medany relocations wrap within the 32-bit space.) */
63	#define VX_ABS_LINKER_SYM(sym) ({                                  \
64	  size_t __v;                                                      \
65	  __asm__("lui %0, %%hi(" #sym ")\n\t addi %0, %0, %%lo(" #sym ")" \
66	          : "=r"(__v));                                            \
67	  __v;                                                             \
68	})
69	
70	void __init_tls(void) {
71	  extern char __tdata_start[];
72	
73	  // TLS memory initialization
74	  register char *__thread_self __asm__ ("tp");
75	  memcpy(__thread_self, __tdata_start, VX_ABS_LINKER_SYM(__tdata_size));
76	  memset(__thread_self + VX_ABS_LINKER_SYM(__tbss_offset), 0,
77	         VX_ABS_LINKER_SYM(__tbss_size));
78	}
