92	// Iterate over all the init routines.
93	void __libc_init_array (void) {
94	  size_t count;
95	  size_t i;
96	
97	  count = __preinit_array_end - __preinit_array_start;
98	  for (i = 0; i < count; i++)
99	    __preinit_array_start[i] ();
100	
101	#ifdef HAVE_INIT_FINI
102	  _init ();
103	#endif
104	
105	  count = __init_array_end - __init_array_start;
106	  for (i = 0; i < count; i++)
107	    __init_array_start[i] ();
108	}
109	#endif
110	
111	#ifdef HAVE_INITFINI_ARRAY
112	extern void (*__fini_array_start []) (void) __attribute__((weak));
113	extern void (*__fini_array_end []) (void) __attribute__((weak));
114	
115	#ifdef HAVE_INIT_FINI
116	extern void _fini (void);
117	#endif
118	
119	/* Run all the cleanup routines.  */
120	void __libc_fini_array (void) {
121	  size_t count;
122	  size_t i;
123	
124	  count = __fini_array_end - __fini_array_start;
125	  for (i = count; i > 0; i--)
126	    __fini_array_start[i-1] ();
127	
128	#ifdef HAVE_INIT_FINI
129	  _fini ();
130	#endif
131	}
132	#endif
