49	static void parse_args(int argc, char **argv) {
50	  	int c;
51	  	while ((c = getopt(argc, argv, "shdp:V")) != -1) {
52	    	switch (c) {
53	      case 's':
54	        showStats = true;
55	        break;
56	      case 'd':
57	        debug_mode = true;
58	        break;
59	      case 'p':
60	        rbb_port = static_cast<uint16_t>(atoi(optarg));
61	        break;
62	      case 'V':
63	        debug_verbose = true;
64	        break;
65	    	case 'h':
66	      	show_usage();
67	      	exit(0);
68	    		break;
69	    	default:
70	      	show_usage();
71	      	exit(-1);
72	    	}
73		}
74	
75		if (optind < argc) {
76			program = argv[optind];
77	    if (!debug_mode) {
78	      std::cout << "Running " << program << "..." << std::endl;
79	    }
80		} else {
81			show_usage();
82	    exit(-1);
83		}
